package main

import (
	"fmt"
	"math/big"
	"strings"
)

// gammaRel emits gammaRelPieces: Γ(x) for x in [10, 172) on pieces of width
// 1/8, as G(c) · P(s) with s = x - c, c the piece's centre (a multiple of
// 1/16, so s is exact), G(c) = Γ(c) as a double-double and P the degree-13
// Chebyshev interpolant of Γ(c+s)/Γ(c) on [-1/16, 1/16] (relative error
// below 2^-70) written in monomials: P(s) = 1 + s(a1 + s(a2 + s(a3 + s R(s)))),
// a1..a3 as double-doubles (their terms reach 0.32, 0.05 and 0.006 of P and
// must be carried to 2^-62), R from a4 on in float64 (the largest term left is
// 2^-60 of P, rounded to 2^-113).
func gammaRel() {
	const (
		nsub = 8
		x0   = 10
		npc  = 1293 // pieces: x up to 171.625, past gammaMax = 171.6244
		deg  = 13
	)
	o := newOracle()
	c := c200
	gam := evalFn(o, "gamma", 200)
	worst := new(big.Float).SetPrec(200)
	p("// Code generated by testdata/gen/fitgo gamma-rel; DO NOT EDIT.")
	p("//")
	p("// gammaRelPieces: Γ(x) = G(c) P(x - c) for x in [%d, %d + %d/%d) on pieces of width 1/%d;", x0, x0, npc, nsub, nsub)
	p("// degree-%d Chebyshev interpolants of Γ(c+s)/Γ(c), mpmath %s at 200 bits.", deg, mpmathVersion)
	p("")
	p("package special")
	p("")
	var body strings.Builder
	for j := 0; j < npc; j++ {
		a := c.add(c.i(x0), c.quo(c.i(int64(j)), c.i(nsub)))
		b := c.add(c.i(x0), c.quo(c.i(int64(j+1)), c.i(nsub)))
		pad := c.mul(c.sub(b, a), new(big.Float).SetMantExp(c.i(1), -20))
		gc := gam([]*big.Float{c.quo(c.add(a, b), c.i(2))})[0]
		f := func(xs []*big.Float) []*big.Float {
			vs := gam(xs)
			for i := range vs {
				vs[i] = c.quo(vs[i], gc)
			}
			return vs
		}
		cm, co := chebInterp(o, f, c.sub(a, pad), c.add(b, pad), deg)
		if cm.Cmp(c.quo(c.add(a, b), c.i(2))) != 0 {
			check(fmt.Errorf("centre"))
		}
		worst = worstRel(o, f, a, b, cm, co, worst)
		// the constant term is 1 up to the interpolation error
		if e := c.abs(c.sub(co[0], c.i(1))); e.Cmp(new(big.Float).SetMantExp(c.i(1), -66)) > 0 {
			check(fmt.Errorf("piece %d: constant term %s", j, nstr3(e)))
		}
		dd := func(v *big.Float) (float64, float64) {
			h := fl(v)
			return h, fl(c.sub(v, c.f(h)))
		}
		gh, gl := dd(gc)
		a1h, a1l := dd(co[1])
		a2h, a2l := dd(co[2])
		a3h, a3l := dd(co[3])
		fmt.Fprintf(&body, "\t// x in [%d + %d/%d, %d + %d/%d)\n", x0, j, nsub, x0, j+1, nsub)
		fmt.Fprintf(&body, "\t{c: %s, gh: %s, gl: %s, a1: %s, a1l: %s, a2: %s, a2l: %s, a3: %s, a3l: %s, r: [10]float64{",
			pyRepr(fl(cm)), pyRepr(gh), pyRepr(gl), pyRepr(a1h), pyRepr(a1l), pyRepr(a2h), pyRepr(a2l), pyRepr(a3h), pyRepr(a3l))
		var rs []string
		for i := deg; i >= 4; i-- { // Horner order: a13 first
			rs = append(rs, pyRepr(fl(co[i])))
		}
		fmt.Fprintf(&body, "%s}},\n", strings.Join(rs, ", "))
	}
	if worst.Cmp(new(big.Float).SetMantExp(c.i(1), -66)) > 0 {
		check(fmt.Errorf("interpolation error %s", nstr3(worst)))
	}
	p("// Max interpolation error over all pieces: %s relative.", nstr3(worst))
	p("var gammaRelPieces = [...]gammaRelPiece{")
	out.WriteString(body.String())
	p("}")
}
